from ute_common_validator.validator import IsString, IsOneOf

from .base_cl_tool import BaseClToolInterface


class FaultDiagnosisInterface(BaseClToolInterface):
    """Keyword for Fault Diagnosis related commands."""

    def start_fault_diagnosis(self, trigger_number=',,,,', validity='permanent', timeout='5min', **kwargs):
        """
        Saving BTS runtime log when one of the five predefined faults is arised

        :param integer/list trigger_number: Raw fault number which triggers saving of the BTS system log, when arised.
                                            If not specified, all five fault numbers will be off (i.e. ',,,,'). Value range is 0-9999.
                                            If there are multiple numbers (up to five values), join them with ',' (e.g. 1,11,111)
                                            For cases where special index must be off, values can be specified as such (e.g. ,,11,111)
        :param string validity: Validity defines whether the settings are stored to non-volatile or volatile memory in BTS.\
                                Defaults to permanent. Supported values are: permanent, until_site_reet

        :return: Path(s) of collected file(s).
        :rtype: list
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        trigger_number = str(trigger_number).strip()
        validity = validity.strip()
        self._check_validity_value(validity)
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'triggerNumber': trigger_number, 'validity': validity}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='faultdiagnosis', params=params, trs_ip=ne, flags=flags)

    def _check_validity_value(self, validity):
        IsString().check(validity)
        IsOneOf('permanent', 'until_site_reset').check(validity)
